func placement_keeps_routes(cell: Vector2i, origins: Array[Vector2i]) -> bool:
	var blocked := func(c: Vector2i) -> bool:
		return false if c == cell else is_open(c)
	if not AStar.route_exists(spawn, exit_cell, blocked):
		return false
	for origin in origins:
		if origin == cell:
			continue
		if not AStar.route_exists(origin, exit_cell, blocked):
			return false
	return true

func take_damage(amount: float) -> void:
	if finished:
		return
	hit_flash = 0.14
	health -= amount
	if health <= 0.0:
		health = 0.0
		finished = true
		died.emit(self)

func _tick_status(delta: float) -> void:
	if hit_flash > 0.0:
		hit_flash = maxf(0.0, hit_flash - delta)
	if ice_time > 0.0:
		ice_time = maxf(0.0, ice_time - delta)
	if poison_time > 0.0:
		poison_time = maxf(0.0, poison_time - delta)
		poison_accumulator += delta
		while poison_accumulator >= poison_tick and not finished:
			poison_accumulator -= poison_tick
			take_damage(poison_damage)

